def build(data):
    types=data['defined_profiles']['types'];lookup={r['id']:r for r in data['records']};type_of={id:t['id'] for t in types for id in t['ids']};members=data['catalog']['memberships'];keys=set.intersection(*[{lookup[id]['key'] for id in type_of if lookup[id]['cohort']==c and lookup[id]['sex']==sex} for c in range(4) for sex in range(2)]);keys=sorted(keys);N=len(keys);distributions=[];territories=[]
